#!/bin/bash
# RECON runner for project 'tinymediamanager' (from DXP inspect 2026-10-11)
docker network inspect 'tinymediamanager_default' >/dev/null 2>&1 || docker network create 'tinymediamanager_default'
docker run -d --name 'tinymediamanager' --restart 'unless-stopped' --cap-add CAP_SYS_NICE --network-alias 'tinymediamanager' --env 'LANG=en_US.UTF-8' --env 'GROUP_ID=10' --env 'LC_ALL=en_US.UTF-8' --env 'USER_ID=999' --env 'APP-NICENESS=-5' --env 'X11VNC_PASSWORD_ON=false' --env 'JAVA_HEAP_MAX=2048m' --env 'JAVA_OPTS=-Xmx2048m -Xms512m' --env 'ALLOW_DIRECT_VNC=true' --env 'APP=tinyMediaManager' --env 'UMASK=0022' --env 'PASSWORD=' --env 'LC_TIME=C.UTF-8' --publish '4000:4000/tcp' --publish '5900:5900/tcp' --volume '/volume1/Network Share/Videos/SuperHero Movies:/superhero_movies' --volume '/volume1/Network Share/Videos/Television:/television' --volume '/volume1/docker/tinymediamanager/data:/data' --volume '/volume1/Network Share/Videos/Documentaries:/documentaries' --volume '/volume1/Network Share/Videos/Movies:/movies' --volume '/volume1/Network Share/Videos/Music Videos:/music_videos' --volume '/volume1/Network Share/Videos/Kids Movies:/kids_movies' --volume '/volume1/Network Share/Videos/Kids Television:/kids_tv' --volume '/volume1/Network Share/Videos/Christmas & Holiday Movies:/christmas' --volume '/volume1/Network Share/Videos/Horror:/horror' --volume '/volume1/Network Share/Videos/Standup:/standup' --network 'tinymediamanager_default' --entrypoint '/usr/local/bin/startup.sh' '/app/tinyMediaManager' '-Dtmm.contentfolder=/data'
docker network connect 'tinymediamanager_default' 'tinymediamanager' 2>/dev/null || true
echo RUNNER-DONE-tinymediamanager